{
  "name": "网络套接字客户端",
  "name_en": "Network Socket Client",
  "manufacturer": "",
  "description": "这不是一台特定的实验仪器，而是一个用于与网络化实验设备保持开放套接字连接的通用客户端。它可连接指定地址和端口，发送文本命令、接收返回消息并读取日志流，常用于远程控制数据采集系统或其他基于网络接口的实验设备。",
  "description_en": "This is not a specific laboratory instrument, but a generic client for maintaining an open socket connection to networked lab equipment. It connects to a specified address and port, sends text commands, receives returned messages, and reads log streams, making it useful for remote control of data acquisition systems or other instruments with network interfaces.",
  "tag_hints": [
    "TCP socket communication",
    "remote instrument control",
    "networked DAQ",
    "log streaming",
    "text command interface"
  ],
  "actions": [
    {
      "action_name": "auto-receive_message",
      "description": "从套接字接收消息，直到匹配指定的行终止模式。",
      "description_en": "Receive a message from the socket until the specified line terminator pattern is matched."
    },
    {
      "action_name": "auto-send",
      "description": "通过套接字发送消息。",
      "description_en": "Send a message through the socket."
    },
    {
      "action_name": "auto-has_data",
      "description": "检查套接字上是否有可读取的数据。",
      "description_en": "Check whether data is available to read on the socket."
    },
    {
      "action_name": "auto-close",
      "description": "关闭当前套接字连接。",
      "description_en": "Close the current socket connection."
    },
    {
      "action_name": "auto-addr",
      "description": "获取远程网络地址。",
      "description_en": "Get the remote network address."
    },
    {
      "action_name": "auto-port",
      "description": "获取远程端口号。",
      "description_en": "Get the remote port number."
    },
    {
      "action_name": "auto-closeall",
      "description": "关闭所有打开的客户端连接。",
      "description_en": "Close all open client connections."
    }
  ]
}

